        ["WFE"] = "SYS_SERIAL",
        ["WFI"] = "SYS_SERIAL",
        ["XNOR"] = "ALU",
        ["XOR"] = "ALU",
        ["XORI"] = "ALU",
        ["YIELD"] = "SYS_SERIAL",
        ["ZEXT.H"] = "ALU",
        ["ZEXT.W"] = "ALU",
    };

    public static bool TryGetDescriptor(uint opcode, out GeneratedIsaDescriptor descriptor)
    {
        foreach (var candidate in Descriptors) if (candidate.Opcode == opcode) { descriptor = candidate; return true; }
        descriptor = default; return false;
    }

    public static readonly OpcodeInfo[] Opcodes = CreateOpcodeInfos();
    private static OpcodeInfo[] CreateOpcodeInfos()
    {
        var opcodes = new OpcodeInfo[Descriptors.Length];
        for (var index = 0; index < Descriptors.Length; index++) { var descriptor = Descriptors[index]; opcodes[index] = new OpcodeInfo(descriptor.Opcode, descriptor.Mnemonic, descriptor.OpcodeCategory, descriptor.OperandSchema == "operands-0" ? (byte)0 : byte.Parse(descriptor.OperandSchema.AsSpan(9)), descriptor.InstructionFlags, descriptor.ExecutionLatency, descriptor.MemoryBandwidth, descriptor.StaticClass, descriptor.Serialization); }
        return opcodes;
    }
}
